// iconCommand is one command of an icon's path: its letter and its numbers.
type iconCommand struct {
	op     byte
	values []float64
}

// parseIconPath reads a path of packingIconPaths into its commands.
//
// Returns:
//   - the commands in order.
//   - an error for anything but M, L, C and Z with their numbers.
func parseIconPath(path string) ([]iconCommand, error) {
	commands := make([]iconCommand, 0, 16)
	for _, field := range strings.FieldsFunc(path, func(r rune) bool { return r == ' ' }) {
		for field != "" {
			if op := field[0]; op == 'M' || op == 'L' || op == 'C' || op == 'Z' {
				commands = append(commands, iconCommand{op: op})
				field = field[1:]
				continue
			}
			end := strings.IndexAny(field, "MLCZ")
			if end < 0 {
				end = len(field)
			}
			value, err := strconv.ParseFloat(field[:end], 64)
			if err != nil || len(commands) == 0 {
				return nil, fmt.Errorf("icon path: unexpected %q", field)
			}
			last := &commands[len(commands)-1]
			last.values = append(last.values, value)
			field = field[end:]
		}
	}
	want := map[byte]int{'M': 2, 'L': 2, 'C': 6, 'Z': 0}
	for _, command := range commands {
		if len(command.values) != want[command.op] {
			return nil, fmt.Errorf("icon path: %c takes %d numbers, has %d", command.op, want[command.op],
				len(command.values))
		}
	}
	return commands, nil
}

// drawPackingIcon fills a category's icon in the current fill colour, as a
// square of size with its corner at x, y. An icon outside the set is drawn as
// the one of "other".
func drawPackingIcon(pdf *fpdf.Fpdf, icon domain.PackingIcon, x, y, size float64) {
	paths, ok := packingIconPaths[string(icon)]
	if !ok {
		paths = packingIconPaths[string(domain.PackingIconOther)]
	}
	scale := size / 16
	at := func(values []float64, index int) (float64, float64) {
		return x + values[index]*scale, y + values[index+1]*scale
	}
	for _, path := range paths {
		commands, err := parseIconPath(path)
		if err != nil {
			// The paths are fixed and checked by a test; a broken one leaves
			// the badge empty rather than the document unwritten.
			continue
		}
		for _, command := range commands {
			switch command.op {
			case 'M':
				pdf.MoveTo(at(command.values, 0))
			case 'L':
				pdf.LineTo(at(command.values, 0))
			case 'C':
				x0, y0 := at(command.values, 0)
				x1, y1 := at(command.values, 2)
				x2, y2 := at(command.values, 4)
				pdf.CurveBezierCubicTo(x0, y0, x1, y1, x2, y2)
			case 'Z':
				pdf.ClosePath()
			}
		}
		// One path's contours are filled together, so the inner ones cut
		// holes by the nonzero rule, as in the browser.
		pdf.DrawPath("F")
	}
}
